SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='5af4e182-89b1-52d7-ab97-b3ec53421232'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('82a9f8c8-1305-5ddf-b58f-43e5c80152da','d4bc7c2b-36d3-592c-8414-f128c34914e7')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='5af4e182-89b1-52d7-ab97-b3ec53421232'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='5af4e182-89b1-52d7-ab97-b3ec53421232'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('82a9f8c8-1305-5ddf-b58f-43e5c80152da','d4bc7c2b-36d3-592c-8414-f128c34914e7')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='5af4e182-89b1-52d7-ab97-b3ec53421232'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='82a9f8c8-1305-5ddf-b58f-43e5c80152da' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-01-missing-history' AND q.fingerprint='7b88cd99df524c7371b3a760b7b94fd5e2a573dc3264246faf242d7ea380fd5a'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-01-missing-history","status":"ok","value":{"customerProfileId":"5af4e182-89b1-52d7-ab97-b3ec53421232","userId":"dceaa8d2-3a87-56aa-8309-2ec05b7a2865","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"82a9f8c8-1305-5ddf-b58f-43e5c80152da","semanticKey":"customer-controls-customer-01-missing-history","fingerprint":"7b88cd99df524c7371b3a760b7b94fd5e2a573dc3264246faf242d7ea380fd5a","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='391617be-944a-5519-8b9f-93bc0ea0b5d8' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='93f372b3-1d06-5e22-adab-369e1152ab65' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"5af4e182-89b1-52d7-ab97-b3ec53421232"},"prior":null,"committed":{"id":"5af4e182-89b1-52d7-ab97-b3ec53421232","userId":"dceaa8d2-3a87-56aa-8309-2ec05b7a2865","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='5af4e182-89b1-52d7-ab97-b3ec53421232' AND c.user_id='dceaa8d2-3a87-56aa-8309-2ec05b7a2865' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-01-missing-history' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='59b62cfd-ace9-5ddf-84e7-5739976aec98' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"5af4e182-89b1-52d7-ab97-b3ec53421232","userId":"dceaa8d2-3a87-56aa-8309-2ec05b7a2865","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='b99269c4-e7b0-5d8d-a877-4aa105e91f17' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"dceaa8d2-3a87-56aa-8309-2ec05b7a2865","track":"customer","customerProfileId":"5af4e182-89b1-52d7-ab97-b3ec53421232","sourceCreationRevision":"0","sourceCreationReceipt":"82a9f8c8-1305-5ddf-b58f-43e5c80152da","semanticKey":"customer_buyer_profile/5af4e182-89b1-52d7-ab97-b3ec53421232/default-free-enrollment/v1"}'::jsonb)))=2));
